body.content:
.article-template > *:first-child:not(.article-template__hero-container) {
  margin-top: 4rem;
}

@media screen and (min-width: 750px) {
  .article-template > *:first-child:not(.article-template__hero-container) {
    margin-top: calc(4rem + var(--page-width-margin));
  }
}

.article-template__breadcrumb {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  align-items: center;
  margin-top: 2.4rem;
  color: rgba(var(--color-foreground), 0.6);
  font-size: 1.2rem;
  letter-spacing: 0.08rem;
  text-transform: uppercase;
}

.article-template__breadcrumb a {
  color: inherit;
  text-decoration: none;
}

.article-template__hero-container {
  max-width: 120rem;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.article-template__hero-small {
  height: 24rem;
}

.article-template__hero-medium {
  height: 34rem;
}

.article-template__hero-large {
  height: 44rem;
}

@media screen and (min-width: 750px) and (max-width: 989px) {
  .article-template__hero-small {
    height: 28rem;
  }

  .article-template__hero-medium {
    height: 40rem;
  }

  .article-template__hero-large {
    height: 52rem;
  }
}

@media screen and (min-width: 990px) {
  .article-template__hero-small {
    height: 30rem;
  }

  .article-template__hero-medium {
    height: 46rem;
  }

  .article-template__hero-large {
    height: 58rem;
  }
}

.article-template__hero-container .media {
  overflow: hidden;
  border-radius: 3rem;
  box-shadow: 0 2.6rem 5rem rgba(var(--color-shadow), 0.1);
}

.article-template__hero-cover {
  overflow: hidden;
  border-radius: 3rem;
  box-shadow: 0 2.6rem 5rem rgba(var(--color-shadow), 0.1);
}

.article-template__hero-cover .article-editorial-cover {
  min-height: 100%;
}

.article-template__hero-fallback {
  background: rgba(var(--color-foreground), 0.04);
}

.article-template__hero-container img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.article-template__header {
  margin-top: 4.4rem;
  margin-bottom: 2rem;
  display: grid;
  gap: 1.2rem;
}

@media screen and (min-width: 750px) {
  .article-template__header {
    margin-top: 5rem;
  }
}

.article-template__eyebrow {
  margin: 0;
  color: rgba(var(--color-foreground), 0.6);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: 0.22rem;
  text-transform: uppercase;
}

.article-template__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem 1.2rem;
  color: rgba(var(--color-foreground), 0.62);
  font-size: 1.1rem;
  letter-spacing: 0.18rem;
  text-transform: uppercase;
}

.article-template__title {
  margin: 0;
  font-size: clamp(3.2rem, 6vw, 5.8rem);
  line-height: 1.02;
}

.article-template__title:not(:only-child) {
  margin-bottom: 0;
}

.article-template__link {
  font-size: 1.8rem;
  display: flex;
  justify-content: center;
  align-items: center;
  text-decoration: none;
}

.article-template__link .icon-wrap {
  display: flex;
  margin-right: 1rem;
  transform: rotate(180deg);
}

.article-template__content {
  margin-top: 3.2rem;
  margin-bottom: 0;
}

.article-template__content > * {
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
}

.article-template__content p,
.article-template__content li {
  color: rgba(var(--color-foreground), 0.8);
  font-size: 1.75rem;
  line-height: 1.8;
}

.article-template__content h2,
.article-template__content h3,
.article-template__content h4 {
  margin-top: 4rem;
  margin-bottom: 1.6rem;
  line-height: 1.12;
}

.article-template__content ul,
.article-template__content ol {
  padding-left: 2.4rem;
}

.article-template__content blockquote {
  margin: 3rem auto;
  padding: 2.2rem 2.4rem;
  border-left: 0.3rem solid rgba(var(--color-foreground), 0.14);
  border-radius: 0 2rem 2rem 0;
  background: rgba(var(--color-foreground), 0.03);
}

.article-template__content img {
  border-radius: 2rem;
}

.article-template__content table {
  display: block;
  overflow-x: auto;
}

.article-template__social-sharing {
  margin-top: 3rem;
}

.article-template__social-sharing + header,
.article-template__social-sharing + .article-template__content {
  margin-top: 1.5rem;
}

.article-template__shop-links {
  margin-top: 4rem;
}

.article-template__shop-card {
  padding: 2.6rem 2.2rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2.8rem;
  background: linear-gradient(135deg, rgba(var(--color-background), 1) 0%, rgba(var(--color-foreground), 0.03) 100%);
}

.article-template__shop-eyebrow,
.article-template__related-eyebrow {
  margin: 0 0 1rem;
  color: rgba(var(--color-foreground), 0.58);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.18rem;
  text-transform: uppercase;
}

.article-template__shop-title,
.article-template__related-title {
  margin: 0;
  line-height: 1.08;
}

.article-template__shop-grid {
  display: grid;
  gap: 1rem;
  margin-top: 2rem;
}

.article-template__shop-link {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding: 1.4rem 1.6rem;
  border-radius: 1.8rem;
  background: rgb(var(--color-background));
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  color: inherit;
  text-decoration: none;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.article-template__shop-link:hover {
  transform: translateY(-0.2rem);
  border-color: rgba(var(--color-foreground), 0.18);
}

.article-template__shop-link-copy {
  display: grid;
  gap: 0.35rem;
  flex: 1 1 auto;
}

.article-template__shop-link-title {
  font-size: 1.7rem;
  font-weight: 600;
  line-height: 1.35;
}

.article-template__shop-link-caption {
  color: rgba(var(--color-foreground), 0.64);
  font-size: 1.3rem;
  line-height: 1.5;
}

.article-template__recommended-products {
  margin-top: 4rem;
}

.article-template__recommended-card {
  padding: 2.6rem 2.2rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2.8rem;
  background: linear-gradient(135deg, rgba(var(--color-background), 1) 0%, rgba(var(--color-foreground), 0.04) 100%);
}

.article-template__recommended-card--fallback {
  display: grid;
  gap: 1.6rem;
  justify-items: start;
}

.article-template__recommended-eyebrow {
  margin: 0 0 1rem;
  color: rgba(var(--color-foreground), 0.58);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.18rem;
  text-transform: uppercase;
}

.article-template__recommended-title {
  margin: 0;
  line-height: 1.08;
}

.article-template__recommended-grid {
  display: grid;
  gap: 1.6rem;
  margin-top: 2rem;
}

.article-template__recommended-product {
  display: grid;
  gap: 1.6rem;
  padding: 1.4rem;
  border-radius: 2.2rem;
  background: rgb(var(--color-background));
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
}

.article-template__recommended-product-image {
  display: block;
  overflow: hidden;
  border-radius: 1.8rem;
  background: rgba(var(--color-foreground), 0.04);
}

.article-template__recommended-product-image img,
.article-template__recommended-product-placeholder {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1.1;
  object-fit: cover;
}

.article-template__recommended-product-info {
  display: grid;
  gap: 1rem;
  align-content: start;
}

.article-template__recommended-product-title {
  margin: 0;
  font-size: 1.9rem;
  line-height: 1.3;
}

.article-template__recommended-product-title a {
  color: inherit;
  text-decoration: none;
}

.article-template__recommended-price .price__container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem 1.2rem;
  align-items: baseline;
}

.article-template__recommended-price .price-item {
  font-size: 1.6rem;
}

.article-template__recommended-product-link {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  color: inherit;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: 0.08rem;
  text-decoration: none;
  text-transform: uppercase;
}

.article-template__recommended-fallback-link {
  min-width: 0;
}

@media screen and (min-width: 750px) {
  .article-template__recommended-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.article-template__related {
  margin-top: 5rem;
}

.article-template__related-header {
  display: grid;
  gap: 1rem;
  margin-bottom: 2rem;
}

.article-template__related-grid {
  display: grid;
  gap: 2rem;
}

.article-template__comment-wrapper {
  margin-top: 5rem;
  padding: 2.7rem 0;
}

@media screen and (min-width: 750px) {
  .article-template__shop-card {
    padding: 3rem;
  }

  .article-template__shop-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .article-template__related {
    margin-top: 6rem;
  }

  .article-template__related-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .article-template__comment-wrapper {
    margin-top: 6rem;
    padding: 3.6rem 0;
  }
}

.article-template__comment-wrapper h2 {
  margin-top: 0;
}

.article-template__comments {
  margin-bottom: 5rem;
}

@media screen and (min-width: 750px) {
  .article-template__comments {
    margin-bottom: 7rem;
  }
}

.article-template__comments-fields {
  margin-bottom: 4rem;
}

.article-template__comments-comment {
  color: rgba(var(--color-foreground), 0.75);
  background-color: rgb(var(--color-background));
  margin-bottom: 1.5rem;
  padding: 2rem 2rem 1.5rem;
}

@media screen and (min-width: 750px) {
  .article-template__comments-comment {
    padding: 2rem 2.5rem;
  }
}

.article-template__comments-comment p {
  margin: 0 0 1rem;
}

.article-template__comment-fields > * {
  margin-bottom: 3rem;
}

@media screen and (min-width: 750px) {
  .article-template__comment-fields {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-column-gap: 4rem;
  }
}

.article-template__comment-warning {
  margin: 2rem 0 2.5rem;
}

@media screen and (min-width: 990px) {
  .article-template__comments .pagination-wrapper {
    margin: 5rem 0 8rem;
  }
}

.article-template__back:last-child {
  margin-bottom: 3.2rem;
}

/* ── Author Bio ── */
.article-template__author {
  margin-top: 4rem;
}

.article-template__author-card {
  display: flex;
  gap: 2rem;
  padding: 2.4rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2rem;
  background: rgba(var(--color-foreground), 0.02);
}

.article-template__author-avatar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 5.6rem;
  height: 5.6rem;
  border-radius: 50%;
  background: rgba(var(--color-foreground), 0.08);
  font-size: 2rem;
  font-weight: 700;
  color: rgba(var(--color-foreground), 0.7);
}

.article-template__author-info {
  display: grid;
  gap: 0.4rem;
}

.article-template__author-label {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

.article-template__author-name {
  margin: 0;
  font-size: 1.8rem;
  font-weight: 600;
}

.article-template__author-bio {
  margin: 0;
  font-size: 1.5rem;
  line-height: 1.65;
  color: rgba(var(--color-foreground), 0.7);
}

/* ── Table of Contents ── */
.article-toc {
  margin-bottom: 3.2rem;
  padding: 2.2rem 2.4rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2rem;
  background: rgba(var(--color-foreground), 0.02);
}

.article-toc__label {
  margin: 0 0 1.2rem;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

.article-toc__list {
  margin: 0;
  padding-left: 2rem;
  list-style: decimal;
}

.article-toc__list li {
  margin-bottom: 0.6rem;
  font-size: 1.5rem;
  line-height: 1.5;
}

.article-toc__list a {
  color: rgba(var(--color-foreground), 0.85);
  text-decoration: none;
  border-bottom: 0.1rem solid rgba(var(--color-foreground), 0.12);
  transition: color 0.2s ease, border-color 0.2s ease;
}

.article-toc__list a:hover {
  color: rgb(var(--color-foreground));
  border-color: rgba(var(--color-foreground), 0.4);
}

/* ── Mid-Article CTA ── */
.article-cta-inline {
  margin: 3.2rem auto;
  padding: 2.4rem;
  border-radius: 2rem;
  background: linear-gradient(135deg, rgba(var(--color-foreground), 0.03) 0%, rgba(var(--color-foreground), 0.06) 100%);
  text-align: center;
}

.article-cta-inline__text {
  margin: 0 0 1.2rem;
  font-size: 1.8rem;
  font-weight: 600;
  color: rgb(var(--color-foreground));
}

.article-cta-inline__button {
  display: inline-block;
}

/* ── Improved Heading Hierarchy ── */
.article-template__content h2 {
  font-size: clamp(2.4rem, 4vw, 3.2rem);
  font-weight: 700;
  margin-top: 4.8rem;
  margin-bottom: 1.8rem;
  padding-bottom: 1rem;
  border-bottom: 0.1rem solid rgba(var(--color-foreground), 0.08);
}

.article-template__content h3 {
  font-size: clamp(1.8rem, 3vw, 2.4rem);
  font-weight: 600;
  margin-top: 3.2rem;
  margin-bottom: 1.2rem;
  color: rgba(var(--color-foreground), 0.9);
}

.article-template__content h4 {
  font-size: clamp(1.6rem, 2.5vw, 2rem);
  font-weight: 600;
  margin-top: 2.4rem;
  margin-bottom: 1rem;
  color: rgba(var(--color-foreground), 0.82);
}

/* ── Shop Module Arrow ── */
.article-template__shop-arrow {
  font-size: 1.8rem;
  transition: transform 0.2s ease;
}

.article-template__shop-link:hover .article-template__shop-arrow {
  transform: translateX(0.4rem);
}

/* ── Read Time Tag ── */
.article-template__read-time {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 1.1rem;
  letter-spacing: 0.18rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

/* ── Author Credential Badge ── */
.article-template__author-credential {
  display: inline-block;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: 0.08rem;
  color: rgba(var(--color-foreground), 0.55);
  padding-left: 0.6rem;
}

/* ── Social Proof / Testimonial ── */
.article-template__social-proof {
  margin-top: 3.2rem;
}

.article-template__testimonial-card {
  padding: 2.4rem;
  border: 0.1rem solid rgba(var(--color-foreground), 0.08);
  border-radius: 2rem;
  background: rgba(var(--color-foreground), 0.02);
  text-align: center;
}

.article-template__testimonial-label {
  margin: 0 0 1.2rem;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 0.16rem;
  text-transform: uppercase;
  color: rgba(var(--color-foreground), 0.5);
}

.article-template__testimonial-title {
  margin: 0;
  font-size: clamp(2.2rem, 3vw, 3rem);
  line-height: 1.12;
}

.article-template__testimonial-text {
  max-width: 58rem;
  margin: 1rem auto 0;
  font-size: 1.6rem;
  line-height: 1.7;
  color: rgba(var(--color-foreground), 0.72);
}

.article-template__testimonial-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 1rem;
  margin-top: 1.8rem;
}

