    width: auto;
    max-width: calc(100% - 1.3rem);
    margin: 0 !important;
    display: inline-flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.24rem;
    pointer-events: none;
  }

  .page-width--product-main .product-media-progress__meta {
    position: static;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.18rem;
    min-width: 3.85rem;
    padding: 0.28rem 0.56rem;
    border: 0.1rem solid rgba(255, 255, 255, 0.34);
    border-radius: 999px;
    background: rgba(16, 18, 22, 0.62);
    box-shadow: 0 0.45rem 1.1rem rgba(16, 18, 22, 0.2);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    color: rgba(255, 255, 255, 0.94);
    font-size: 0.9rem;
    font-weight: 600;
    letter-spacing: 0.025em;
    line-height: 1;
    font-variant-numeric: tabular-nums;
  }

  .page-width--product-main .product-media-progress__track {
    width: clamp(5rem, 22vw, 6.8rem);
    height: 0.2rem;
    margin-right: 0;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.36);
    overflow: hidden;
  }

  .page-width--product-main .product-media-progress__track::after {
    background: rgba(255, 255, 255, 0.92);
  }

  .page-width--product-main .product__title {
    margin-bottom: 0.6rem !important;
  }

  .page-width--product-main .product__info-container > * + * {
    margin-top: 1.05rem !important;
  }

  .template-product .product__info-container .product__title + [id^='price-'],
  .page-width--product-main .product__info-container .product__title + [id^='price-'] {
    margin-top: 0.35rem !important;
  }

  /* Mobile PDP option controls: cleaner spacing and lighter borders */
  .page-width--product-main .product__info-container variant-selects,
  .page-width--product-main .product__info-container .product-form__quantity {
    width: 100%;
    max-width: 100%;
    margin: 0 0 1.4rem !important;
    padding: 1.25rem 1.2rem;
    border: 1px solid #ece9e6;
    border-radius: 12px;
    background: #ffffff;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input {
    max-width: 100%;
    min-width: 0;
    margin: 0 0 1rem 0 !important;
    padding: 0;
    border: 0;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input:last-child {
    margin-bottom: 0 !important;
  }

  .page-width--product-main .product__info-container .product-form__input .form__label,
  .page-width--product-main .product__info-container .product-form__quantity .quantity__label {
    margin-bottom: 0.6rem !important;
    font-size: 1.05rem !important;
    letter-spacing: 0.08em !important;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input .select,
  .page-width--product-main .product__info-container variant-selects .product-form__input select {
    max-width: 100%;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input select {
    min-height: 4.4rem;
    border: 1px solid #d9d5d1 !important;
    border-radius: 10px !important;
    background: #ffffff !important;
    color: #1f1f1f !important;
    font-size: 1.6rem !important;
    line-height: 1.2;
    padding: 1.1rem 3.8rem 1.1rem 1.2rem !important;
    box-shadow: none !important;
  }

  .page-width--product-main .product__info-container variant-selects .product-form__input select:focus {
    border-color: #1f1f1f !important;
    box-shadow: 0 0 0 0.2rem rgba(31, 31, 31, 0.09) !important;
  }

  .page-width--product-main .product__info-container .product-form__quantity {
    padding-bottom: 1rem;
  }

  .page-width--product-main .product__info-container .product-form__quantity .price-per-item__container {
    max-width: 100%;
    min-width: 0;
  }

  .page-width--product-main .product__info-container .product-form__quantity .quantity {
    min-height: 4.4rem;
    border: 1px solid #d9d5d1 !important;
    border-radius: 10px !important;
    box-shadow: none !important;
    background: #ffffff !important;
  }

  .page-width--product-main .product__info-container .product-form__quantity .quantity__button {
    min-width: 4.2rem;
    width: 4.2rem;
  }

  .page-width--product-main .product__info-container .product-form__quantity .quantity__input {
    font-size: 1.6rem;
    color: #1f1f1f;
  }

  .page-width--product-main .product__info-container .product-form__quantity .quantity__rules {
    margin-top: 0.7rem;
    color: #6c6661;
  }

  .page-width--product-main .product__info-container .product-form__input input[type='radio'] + label {
    border-width: 1px !important;
    box-shadow: none !important;
  }
}
</style>
{% endif %}

</body>
</html>

{{ 'component-card.css' | asset_url | stylesheet_tag }}
{{ 'component-article-card.css' | asset_url | stylesheet_tag }}
{{ 'section-blog-post.css' | asset_url | stylesheet_tag }}

{%- liquid
  assign journal_label = blog.title
  if blog.handle == 'news'
    assign journal_label = 'Style Journal'
  endif
-%}

<article class="article-template" itemscope itemtype="https://schema.org/BlogPosting">
  <nav class="article-template__breadcrumb page-width page-width--narrow" aria-label="breadcrumbs">
    <a href="{{ routes.root_url }}">{{ 'sections.breadcrumbs.home' | t }}</a>
    <span aria-hidden="true">&rsaquo;</span>
    <a href="{{ blog.url }}">{{ journal_label }}</a>
    <span aria-hidden="true">&rsaquo;</span>
    <span>{{ article.title | escape }}</span>
  </nav>
  {%- for block in section.blocks -%}
    {%- case block.type -%}
      {%- when '@app' -%}
        <div class="page-width page-width--narrow">
          {% render block %}
        </div>
      {%- when 'featured_image' -%}
        {%- if article.image or blog.handle == 'news' -%}
          <div
            class="article-template__hero-container{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--fade-in{% endif %}"
            {{ block.shopify_attributes }}
          >
            {%- if blog.handle == 'news' -%}
              {%- capture article_fallback_image_url -%}{% render 'article-featured-image-fallback', article: article, field: 'url' %}{%- endcapture -%}
              {%- capture article_fallback_image_width -%}{% render 'article-featured-image-fallback', article: article, field: 'width' %}{%- endcapture -%}
              {%- capture article_fallback_image_height -%}{% render 'article-featured-image-fallback', article: article, field: 'height' %}{%- endcapture -%}
              {%- capture article_fallback_image_alt -%}{% render 'article-featured-image-fallback', article: article, field: 'alt' %}{%- endcapture -%}
              <div class="article-template__hero-{{ block.settings.image_height }} media article-template__hero-fallback" itemprop="image">
                {% comment %}theme-check-disable RemoteAsset{% endcomment %}
                <img
                  src="{{ article_fallback_image_url | strip }}"
                  loading="eager"
                  fetchpriority="high"
                  width="{{ article_fallback_image_width | strip | default: 1200 }}"
                  height="{{ article_fallback_image_height | strip | default: 1500 }}"
                  alt="{{ article_fallback_image_alt | strip | default: article.title | escape }}"
                >
                {% comment %}theme-check-enable RemoteAsset{% endcomment %}
              </div>
            {%- elsif article.image -%}
              <div
                class="article-template__hero-{{ block.settings.image_height }} media"
                itemprop="image"
                {% if block.settings.image_height == 'adapt' and article.image %}
                  style="padding-bottom: {{ 1 | divided_by: article.image.aspect_ratio | times: 100 }}%;"
                {% endif %}
              >
                <img
                  srcset="
                    {% if article.image.width >= 350 %}{{ article.image | image_url: width: 350 }} 350w,{% endif %}
                    {% if article.image.width >= 750 %}{{ article.image | image_url: width: 750 }} 750w,{% endif %}
                    {% if article.image.width >= 1100 %}{{ article.image | image_url: width: 1100 }} 1100w,{% endif %}
                    {% if article.image.width >= 1500 %}{{ article.image | image_url: width: 1500 }} 1500w,{% endif %}
                    {% if article.image.width >= 2200 %}{{ article.image | image_url: width: 2200 }} 2200w,{% endif %}
                    {% if article.image.width >= 3000 %}{{ article.image | image_url: width: 3000 }} 3000w,{% endif %}
                    {{ article.image | image_url }} {{ article.image.width }}w
                  "
                  sizes="(min-width: {{ settings.page_width }}px) {{ settings.page_width | minus: 100 }}px, (min-width: 750px) calc(100vw - 10rem), 100vw"
                  src="{{ article.image | image_url: width: 1100 }}"
                  loading="eager"
                  fetchpriority="high"
                  width="{{ article.image.width }}"
                  height="{{ article.image.height }}"
                  alt="{{ article.image.alt | default: article.title | escape }}"
                >
              </div>
            {%- else -%}
              {%- capture article_fallback_image_url -%}{% render 'article-featured-image-fallback', article: article, field: 'url' %}{%- endcapture -%}
              {%- capture article_fallback_image_width -%}{% render 'article-featured-image-fallback', article: article, field: 'width' %}{%- endcapture -%}
              {%- capture article_fallback_image_height -%}{% render 'article-featured-image-fallback', article: article, field: 'height' %}{%- endcapture -%}
              {%- capture article_fallback_image_alt -%}{% render 'article-featured-image-fallback', article: article, field: 'alt' %}{%- endcapture -%}
              <div class="article-template__hero-{{ block.settings.image_height }} media article-template__hero-fallback" itemprop="image">
                {% comment %}theme-check-disable RemoteAsset{% endcomment %}
                <img
                  src="{{ article_fallback_image_url | strip }}"
                  loading="eager"
                  fetchpriority="high"
                  width="{{ article_fallback_image_width | strip | default: 1200 }}"
                  height="{{ article_fallback_image_height | strip | default: 1500 }}"
                  alt="{{ article_fallback_image_alt | strip | default: article.title | escape }}"
                >
                {% comment %}theme-check-enable RemoteAsset{% endcomment %}
              </div>
            {%- endif -%}
          </div>
        {%- endif -%}

      {%- when 'title' -%}
        <header
          class="article-template__header page-width page-width--narrow{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--fade-in{% endif %}"
          {{ block.shopify_attributes }}
        >
          <p class="article-template__eyebrow">{{ journal_label }}</p>
          <h1
            class="article-template__title"
            itemprop="headline"
          >
            {{ article.title | escape }}
          </h1>
          {%- if block.settings.blog_show_date or block.settings.blog_show_author -%}
            <div class="article-template__meta caption-with-letter-spacing">
              {%- if block.settings.blog_show_date -%}
                <span
                  class="{% if block.settings.blog_show_author %}circle-divider{% endif %}"
                  itemprop="dateCreated pubdate datePublished"
                >
                  {{- article.published_at | time_tag: format: 'date' -}}
                </span>
              {%- endif -%}
              {%- if block.settings.blog_show_author -%}
                <span class="caption-with-letter-spacing" itemprop="author" itemscope itemtype="https://schema.org/Person">
                  <span itemprop="name">{{ article.author }}</span>
                </span>
                <span class="article-template__author-credential">Family Fashion Editor</span>
              {%- endif -%}
            </div>
          {%- endif -%}
          <div class="article-template__read-time">
            <span>{{ article.content | strip_html | split: ' ' | size | divided_by: 200 | at_least: 1 }} min read</span>
          </div>
        </header>

      {%- when 'content' -%}
        <div
          class="article-template__content page-width page-width--narrow rte{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
          itemprop="articleBody"
          {{ block.shopify_attributes }}
        >
          <nav class="article-toc" aria-label="Table of contents">
            <p class="article-toc__label">In this article</p>
            <ol class="article-toc__list" id="article-toc-list"></ol>
          </nav>
          {{ article.content }}
        </div>
        {% render 'style-journal-internal-links', mode: 'article_inline_cta_data', article: article %}
        <script>
          (function() {
            var content = document.querySelector('.article-template__content');
            var tocList = document.getElementById('article-toc-list');
            if (!content || !tocList) return;
            var headings = content.querySelectorAll('h2');
            if (headings.length < 2) { var toc = content.querySelector('.article-toc'); if (toc) toc.style.display = 'none'; return; }
            headings.forEach(function(h, i) {
              var id = 'section-' + (i + 1); h.setAttribute('id', id);
              var li = document.createElement('li'); var a = document.createElement('a');
              a.href = '#' + id; a.textContent = h.textContent; li.appendChild(a); tocList.appendChild(li);
            });
          })();
        </script>
        <script>
          (function() {
            var content = document.querySelector('.article-template__content');
            if (!content) return;
            var paragraphs = content.querySelectorAll('p');
            if (paragraphs.length < 6) return;
            var ctaData = document.querySelector('.article-template__inline-cta-data');
            var ctaText = ctaData && ctaData.getAttribute('data-inline-cta-text') || 'Ready to start matching?';
            var ctaLabel = ctaData && ctaData.getAttribute('data-inline-cta-label') || 'Shop Matching Outfits';
            var ctaUrl = ctaData && ctaData.getAttribute('data-inline-cta-url') || '/collections/matching-outfits';
            var midPoint = Math.floor(paragraphs.length * 0.4);
            var cta = document.createElement('div');
            cta.className = 'article-cta-inline';
            var ctaCopy = document.createElement('p');
            ctaCopy.className = 'article-cta-inline__text';
            ctaCopy.textContent = ctaText;
            var ctaLink = document.createElement('a');
            ctaLink.href = ctaUrl;
            ctaLink.className = 'article-cta-inline__button button';
            ctaLink.textContent = ctaLabel;
            if (ctaData) {
              ctaLink.setAttribute('data-style-journal-link', 'true');
              ctaLink.setAttribute('data-style-journal-link-type', 'collection');
              ctaLink.setAttribute('data-style-journal-link-placement', 'article_inline_cta');
              ctaLink.setAttribute('data-style-journal-source-article-handle', ctaData.getAttribute('data-inline-cta-article-handle') || '');
              ctaLink.setAttribute('data-style-journal-destination-handle', ctaData.getAttribute('data-inline-cta-collection-handle') || '');
              ctaLink.setAttribute('data-style-journal-destination-title', ctaLabel);
            }
            cta.appendChild(ctaCopy);
            cta.appendChild(ctaLink);
            paragraphs[midPoint].parentNode.insertBefore(cta, paragraphs[midPoint].nextSibling);
          })();
        </script>
        {%- liquid
          assign recommended_products = article.metafields.custom.recommended_products.value
        -%}
        {%- capture recommended_products_markup -%}
            {%- if recommended_products != blank -%}
              {%- for recommended_product in recommended_products limit: 3 -%}
                {%- if recommended_product == blank or recommended_product.url == blank -%}
                  {% continue %}
                {%- endif -%}
                {%- capture recommended_product_alt -%}
                  {% render 'product-image-alt', product: recommended_product, media: recommended_product.featured_media %}
                {%- endcapture -%}
                {%- assign recommended_product_alt = recommended_product_alt | strip -%}
              <article class="article-template__recommended-product">
                <a href="{{ recommended_product.url }}" class="article-template__recommended-product-image">
                  {%- if recommended_product.featured_media -%}
                    <img
                      srcset="
                        {%- if recommended_product.featured_media.width >= 320 -%}{{ recommended_product.featured_media | image_url: width: 320 }} 320w,{%- endif -%}
                        {%- if recommended_product.featured_media.width >= 480 -%}{{ recommended_product.featured_media | image_url: width: 480 }} 480w,{%- endif -%}
                        {%- if recommended_product.featured_media.width >= 640 -%}{{ recommended_product.featured_media | image_url: width: 640 }} 640w,{%- endif -%}
                        {{ recommended_product.featured_media | image_url }} {{ recommended_product.featured_media.width }}w
                      "
                      sizes="(min-width: 990px) 22rem, (min-width: 750px) calc((100vw - 12rem) / 3), calc(100vw - 7rem)"
                      src="{{ recommended_product.featured_media | image_url: width: 480 }}"
                      alt="{{ recommended_product_alt | escape }}"
                      loading="lazy"
                      width="{{ recommended_product.featured_media.width }}"
                      height="{{ recommended_product.featured_media.height }}"
                    >
                  {%- else -%}
                    {{ 'product-apparel-2' | placeholder_svg_tag: 'article-template__recommended-product-placeholder placeholder-svg' }}
                  {%- endif -%}
                </a>
                <div class="article-template__recommended-product-info">
                  <h3 class="article-template__recommended-product-title">
                    <a href="{{ recommended_product.url }}">{{ recommended_product.title | escape }}</a>
                  </h3>
                  {% render 'price', product: recommended_product, use_variant: true, price_class: 'article-template__recommended-price' %}
                  <a
                    href="{{ recommended_product.url }}"
                    class="article-template__recommended-product-link"
                    data-style-journal-link="true"
                    data-style-journal-link-type="product"
                    data-style-journal-link-placement="article_recommended_products"
                    data-style-journal-source-article-handle="{{ article.handle | escape }}"
                    data-style-journal-destination-handle="{{ recommended_product.handle | escape }}"
                    data-style-journal-destination-title="{{ recommended_product.title | escape }}"
                  >
                    Shop now <span aria-hidden="true">&rarr;</span>
                  </a>
                </div>
              </article>
            {%- endfor -%}
          {%- endif -%}
        {%- endcapture -%}
        {%- assign recommended_products_markup = recommended_products_markup | strip -%}

        {%- if recommended_products_markup != blank -%}
          <section class="article-template__recommended-products page-width page-width--narrow{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
            <div class="article-template__recommended-card">
              <p class="article-template__recommended-eyebrow">Shop the edit</p>
              <h2 class="article-template__recommended-title">Recommended products from this guide</h2>
              <div class="article-template__recommended-grid">
                {{ recommended_products_markup }}
              </div>
            </div>
          </section>
        {%- else -%}
          {% render 'style-journal-internal-links', mode: 'article_inline_cta_block', article: article %}
        {%- endif -%}

      {%- when 'share' -%}
        <div
          class="article-template__social-sharing page-width page-width--narrow{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
          {{ block.shopify_attributes }}
        >
          {% assign share_url = request.origin | append: article.url %}
          {% render 'share-button', block: block, share_link: share_url %}
        </div>
    {%- endcase -%}
  {%- endfor -%}

  <section class="article-template__author page-width page-width--narrow{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
    <div class="article-template__author-card">
      <div class="article-template__author-avatar" aria-hidden="true">
        {{ article.author | slice: 0 }}
      </div>
      <div class="article-template__author-info">
        <p class="article-template__author-label">Written by</p>
        <h3 class="article-template__author-name" itemprop="author" itemscope itemtype="https://schema.org/Person">
          <span itemprop="name">{{ article.author }}</span>
        </h3>
        <p class="article-template__author-bio">Dress Like Mommy's editorial team builds practical shopping guides for family matching outfits, mommy and me looks, daddy and me outfits, swimwear, pajamas, and photo-ready seasonal styles.</p>
      </div>
    </div>
  </section>

  <section class="article-template__social-proof page-width page-width--narrow{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
    <div class="article-template__testimonial-card">
      <p class="article-template__testimonial-label">Shop the look</p>
      <h2 class="article-template__testimonial-title">Ready to compare matching outfits?</h2>
      <p class="article-template__testimonial-text">Browse the core collections for mommy and me outfits, daddy and me styles, family matching sets, and vacation-ready swimwear.</p>
      <div class="article-template__testimonial-actions">
        <a href="{{ routes.collections_url }}/mommy-and-me" class="button">Mommy &amp; Me</a>
        <a href="{{ routes.collections_url }}/matching-outfits" class="button button--secondary">Family Matching</a>
      </div>
    </div>
  </section>

  {% render 'style-journal-internal-links', mode: 'article_collection_links', article: article %}

  {%- capture explicit_related_articles_markup -%}
    {% render 'style-journal-internal-links', mode: 'article_related_articles', article: article %}
  {%- endcapture -%}
  {%- assign explicit_related_articles_markup = explicit_related_articles_markup | strip -%}

  {%- if explicit_related_articles_markup != blank -%}
    {{ explicit_related_articles_markup }}
  {%- elsif blog.articles_count > 1 -%}
    <section class="article-template__related page-width{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
      <div class="article-template__related-header">
        <p class="article-template__related-eyebrow">Continue reading</p>
        <h2 class="article-template__related-title">More from {{ journal_label }}</h2>
      </div>
      <div class="article-template__related-grid">
        {%- liquid
          assign related_articles_rendered = 0
          assign related_articles_seen = '|' | append: article.id | append: '|'
          assign primary_related_tag = article.tags.first | strip
        -%}
        {%- if primary_related_tag != blank -%}
          {%- for related_article in blog.articles -%}
            {%- assign related_article_token = '|' | append: related_article.id | append: '|' -%}
            {%- if related_articles_seen contains related_article_token -%}
              {% continue %}
            {%- endif -%}
            {%- unless related_article.tags contains primary_related_tag -%}
              {% continue %}
            {%- endunless -%}
            <div class="article-template__related-item">
              {%- render 'article-card',
                blog: blog,
                article: related_article,
                media_height: 'medium',
                media_aspect_ratio: 1.2,
                show_image: true,
                show_date: true,
                show_author: false,
                show_excerpt: true
              -%}
            </div>
            {%- assign related_articles_rendered = related_articles_rendered | plus: 1 -%}
            {%- assign related_articles_seen = related_articles_seen | append: related_article.id | append: '|' -%}
            {%- if related_articles_rendered == 3 -%}
              {% break %}
            {%- endif -%}
          {%- endfor -%}
        {%- endif -%}
        {%- if related_articles_rendered < 3 -%}
          {%- for related_article in blog.articles -%}
            {%- assign related_article_token = '|' | append: related_article.id | append: '|' -%}
            {%- if related_articles_seen contains related_article_token -%}
              {% continue %}
            {%- endif -%}
            <div class="article-template__related-item">
              {%- render 'article-card',
                blog: blog,
                article: related_article,
                media_height: 'medium',
                media_aspect_ratio: 1.2,
                show_image: true,
                show_date: true,
                show_author: false,
                show_excerpt: true
              -%}
            </div>
            {%- assign related_articles_rendered = related_articles_rendered | plus: 1 -%}
            {%- assign related_articles_seen = related_articles_seen | append: related_article.id | append: '|' -%}
            {%- if related_articles_rendered == 3 -%}
              {% break %}
            {%- endif -%}
          {%- endfor -%}
        {%- endif -%}
      </div>
    </section>
  {%- endif -%}

  <div class="article-template__back element-margin-top center{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
    <a href="{{ blog.url }}" class="article-template__link link animate-arrow">
      <span class="icon-wrap">{% render 'icon-arrow' %}</span>
      {{ 'blogs.article.back_to_blog' | t: title: blog.title }}
    </a>
  </div>
  {%- if blog.comments_enabled? -%}
    <div class="article-template__comment-wrapper background-secondary">
      <div
        id="comments"
        class="page-width page-width--narrow{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}"
      >
        {%- if article.comments_count > 0 -%}
          {%- assign anchor_id = '#Comments-' | append: article.id -%}

          <h2 id="Comments-{{ article.id }}" tabindex="-1">
            {{ 'blogs.article.comments' | t: count: article.comments_count }}
          </h2>
          {% paginate article.comments by 5 %}
            <div class="article-template__comments">
              {%- if comment.status == 'pending' and comment.content -%}
                <article id="{{ comment.id }}" class="article-template__comments-comment">
                  {{ comment.content }}
                  <footer class="right">
                    <span class="circle-divider caption-with-letter-spacing">{{ comment.author }}</span>
                  </footer>
                </article>
              {%- endif -%}

              {%- for comment in article.comments -%}
                <article id="{{ comment.id }}" class="article-template__comments-comment">
                  {{ comment.content }}
                  <footer class="right">
                    <span class="circle-divider caption-with-letter-spacing">{{ comment.author }}</span
                    ><span class="caption-with-letter-spacing">
                      {{- comment.created_at | time_tag: format: 'date' -}}
                    </span>
                  </footer>
                </article>
              {%- endfor -%}
              {% render 'pagination', paginate: paginate, anchor: anchor_id %}
            </div>
          {% endpaginate %}
        {%- endif -%}
        {% form 'new_comment', article %}
          {%- liquid
            assign post_message = 'blogs.article.success'
            if blog.moderated? and comment.status == 'unapproved'
              assign post_message = 'blogs.article.success_moderated'
            endif
          -%}
          <h2>{{ 'blogs.article.comment_form_title' | t }}</h2>
          {%- if form.errors -%}
            <div class="form__message" role="alert">
              <h3 class="form-status caption-large text-body" tabindex="-1" autofocus>
                {% render 'icon-error' %}
                {{ 'templates.contact.form.error_heading' | t }}
              </h3>
            </div>
            <ul class="form-status-list caption-large">
              {%- for field in form.errors -%}
                <li>
                  <a href="#CommentForm-{{ field }}" class="link">
                    {%- if form.errors.translated_fields[field] contains 'author' -%}
                      {{ 'blogs.article.name' | t }}
                    {%- elsif form.errors.translated_fields[field] contains 'body' -%}
                      {{ 'blogs.article.message' | t }}
                    {%- else -%}
                      {{ form.errors.translated_fields[field] }}
                    {%- endif -%}
                    {{ form.errors.messages[field] }}
                  </a>
                </li>
              {%- endfor -%}
            </ul>
          {%- elsif form.posted_successfully? -%}
            <div class="form-status-list form__message" role="status">
              <h3 class="form-status" tabindex="-1" autofocus>
                {% render 'icon-success' %}
                {{ post_message | t }}
              </h3>
            </div>
          {%- endif -%}

          <div
            {% if blog.moderated? == false %}
              class="article-template__comments-fields"
            {% endif %}
          >
            <div class="article-template__comment-fields">
              <div class="field field--with-error">
                <input
                  type="text"
                  name="comment[author]"
                  id="CommentForm-author"
                  class="field__input"
                  autocomplete="name"
                  value="{{ form.author }}"
                  aria-required="true"
                  required
                  {% if form.errors contains 'author' %}
                    aria-invalid="true"
                    aria-describedby="CommentForm-author-error"
                  {% endif %}
                  placeholder="{{ 'blogs.article.name' | t }}"
                >
                <label class="field__label" for="CommentForm-author">
                  {{- 'blogs.article.name' | t }}
                  <span aria-hidden="true">*</span></label
                >
                {%- if form.errors contains 'author' -%}
                  <small id="CommentForm-author-error">
                    <span class="form__message">
                      {%- render 'icon-error' -%}
                      {{- 'blogs.article.name' | t }}
                      {{ form.errors.messages.author }}.</span
                    >
                  </small>
                {%- endif -%}
              </div>
              <div class="field field--with-error">
                <input
                  type="email"
                  name="comment[email]"
                  id="CommentForm-email"
                  autocomplete="email"
                  class="field__input"
                  value="{{ form.email }}"
                  autocorrect="off"
                  autocapitalize="off"
                  aria-required="true"
                  required
                  {% if form.errors contains 'email' %}
                    aria-invalid="true"
                    aria-describedby="CommentForm-email-error"
                  {% endif %}
                  placeholder="{{ 'blogs.article.email' | t }}"
                >
                <label class="field__label" for="CommentForm-email">
                  {{- 'blogs.article.email' | t }}
                  <span aria-hidden="true">*</span></label
                >
                {%- if form.errors contains 'email' -%}
                  <small id="CommentForm-email-error">
                    <span class="form__message">
                      {%- render 'icon-error' -%}
                      {{- 'blogs.article.email' | t }}
                      {{ form.errors.messages.email }}.</span
                    >
                  </small>
                {%- endif -%}
              </div>
            </div>
            <div class="field field--with-error">
              <textarea
                rows="5"
                name="comment[body]"
                id="CommentForm-body"
                class="text-area field__input"
                aria-required="true"
                required
                {% if form.errors contains 'body' %}
                  aria-invalid="true"
                  aria-describedby="CommentForm-body-error"
                {% endif %}
                placeholder="{{ 'blogs.article.message' | t }}"
              >{{ form.body }}</textarea>
              <label class="form__label field__label" for="CommentForm-body">
                {{- 'blogs.article.message' | t }}
                <span aria-hidden="true">*</span></label
              >
            </div>
            {%- if form.errors contains 'body' -%}
              <small id="CommentForm-body-error">
                <span class="form__message">
                  {%- render 'icon-error' -%}
                  {{- 'blogs.article.message' | t }}
                  {{ form.errors.messages.body }}.</span
                >
              </small>
            {%- endif -%}
          </div>
          {%- if blog.moderated? -%}
            <p class="article-template__comment-warning caption">{{ 'blogs.article.moderated' | t }}</p>
          {%- endif -%}
          <input type="submit" class="button" value="{{ 'blogs.article.post' | t }}">
        {% endform %}
      </div>
    </div>
  {%- endif -%}
  {% render 'article-enhanced-schema', article: article, blog: blog %}
</article>

{%- liquid
  assign article_schema_image_url = blank
  assign article_schema_image_width = blank
  assign article_schema_image_height = blank

  if blog.handle == 'news' or article.image == blank
    capture article_schema_image_url
      render 'article-featured-image-fallback', article: article, field: 'url'
    endcapture
    capture article_schema_image_width
      render 'article-featured-image-fallback', article: article, field: 'width'
    endcapture
    capture article_schema_image_height
      render 'article-featured-image-fallback', article: article, field: 'height'
    endcapture
    assign article_schema_image_url = article_schema_image_url | strip
    assign article_schema_image_width = article_schema_image_width | strip
    assign article_schema_image_height = article_schema_image_height | strip
  else
    assign article_schema_image_url = article.image | image_url: width: 1920 | prepend: 'https:'
    assign article_schema_image_width = 1920
    assign article_schema_image_height = 1920 | divided_by: article.image.aspect_ratio | round
  endif
-%}

<script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "Article",
    "articleBody": {{ article.content | strip_html | json }},
    "mainEntityOfPage": {
      "@type": "WebPage",
      "@id": {{ request.origin | append: page.url | json }}
    },
    "headline": {{ article.title | json }},
    {% if article.excerpt != blank %}
      "description": {{ article.excerpt | strip_html | json }},
    {% endif %}
    {% if article_schema_image_url != blank %}
      "image": [
        {{ article_schema_image_url | json }}
      ],
    {% endif %}
    "datePublished": {{ article.published_at | date: '%Y-%m-%dT%H:%M:%SZ' | json }},
    "dateCreated": {{ article.created_at | date: '%Y-%m-%dT%H:%M:%SZ' | json }},
    "author": {
      "@type": "Person",
      "name": {{ article.author | json }}
    },
    "publisher": {
      "@type": "Organization",
      "name": {{ shop.name | json }}
    }
  }
</script>

{% schema %}
{
  "name": "t:sections.main-article.name",
  "tag": "section",
  "class": "section",
  "blocks": [
    {
      "type": "@app"
    },
    {
      "type": "featured_image",
      "name": "t:sections.main-article.blocks.featured_image.name",
      "limit": 1,
      "settings": [
        {
          "type": "select",
          "id": "image_height",
          "options": [
            {
              "value": "adapt",
              "label": "t:sections.main-article.blocks.featured_image.settings.image_height.options__1.label"
            },
            {
              "value": "small",
              "label": "t:sections.main-article.blocks.featured_image.settings.image_height.options__2.label"
            },
            {
              "value": "medium",
              "label": "t:sections.main-article.blocks.featured_image.settings.image_height.options__3.label"
            },
            {
              "value": "large",
              "label": "t:sections.main-article.blocks.featured_image.settings.image_height.options__4.label"
            }
          ],
          "default": "adapt",
          "label": "t:sections.main-article.blocks.featured_image.settings.image_height.label",
          "info": "t:sections.main-article.blocks.featured_image.settings.image_height.info"
        }
      ]
    },
    {
      "type": "title",
      "name": "t:sections.main-article.blocks.title.name",
      "limit": 1,
      "settings": [
        {
          "type": "checkbox",
          "id": "blog_show_date",
          "default": true,
          "label": "t:sections.main-article.blocks.title.settings.blog_show_date.label"
        },
        {
          "type": "checkbox",
          "id": "blog_show_author",
          "default": false,
          "label": "t:sections.main-article.blocks.title.settings.blog_show_author.label"
        }
      ]
    },
    {
      "type": "content",
      "name": "t:sections.main-article.blocks.content.name",
      "limit": 1
    },
    {
      "type": "share",
      "name": "t:sections.main-article.blocks.share.name",
      "limit": 2,
      "settings": [
        {
          "type": "text",
          "id": "share_label",
          "label": "t:sections.main-article.blocks.share.settings.text.label",
          "default": "Share"
        },
        {
          "type": "paragraph",
          "content": "t:sections.main-article.blocks.share.settings.featured_image_info.content"
        },
        {
          "type": "paragraph",
          "content": "t:sections.main-article.blocks.share.settings.title_info.content"
        }
      ]
    }
  ]
}
{% endschema %}

{{ 'component-cart.css' | asset_url | stylesheet_tag }}
{{ 'component-totals.css' | asset_url | stylesheet_tag }}
{{ 'component-price.css' | asset_url | stylesheet_tag }}
{{ 'component-discounts.css' | asset_url | stylesheet_tag }}

{%- style -%}
  .section-{{ section.id }}-padding {
    padding-top: {{ section.settings.padding_top | times: 0.75 | round: 0 }}px;
    padding-bottom: {{ section.settings.padding_bottom | times: 0.75 | round: 0 }}px;
  }

  @media screen and (min-width: 750px) {
    .section-{{ section.id }}-padding {
      padding-top: {{ section.settings.padding_top }}px;
      padding-bottom: {{ section.settings.padding_bottom }}px;
    }
  }
{%- endstyle -%}

<div
  class="gradient color-{{ section.settings.color_scheme }}{% if cart == empty %} is-empty{% endif %}"
  id="main-cart-footer"
  data-id="{{ section.id }}"
>
  <div class="page-width">
    <div class="cart__footer isolate section-{{ section.id }}-padding">
      {%- if settings.show_cart_note -%}
        <cart-note class="cart__note field">
          <label for="Cart-note">{{ 'sections.cart.note' | t }}</label>
          <textarea
            class="text-area field__input"
            name="note"
            form="cart"
            id="Cart-note"
            placeholder="{{ 'sections.cart.note' | t }}"
          >{{ cart.note }}</textarea>
        </cart-note>
      {%- endif -%}

      <div class="cart__blocks">
        {%- comment -%} Discount code field — matches cart drawer {%- endcomment -%}
        {%- if cart != empty -%}
          <div class="cart-page__discount">
            <div class="cart-page__discount-toggle">
              <button type="button" class="cart-page__discount-btn" aria-expanded="false" onclick="this.setAttribute('aria-expanded', this.getAttribute('aria-expanded') === 'false' ? 'true' : 'false'); this.closest('.cart-page__discount').querySelector('.cart-page__discount-form').classList.toggle('is-open');">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
                {{ 'sections.cart.discount_code_toggle' | t }}
              </button>
            </div>
            <div class="cart-page__discount-form">
              <div class="cart-page__discount-input-wrap">
                <input type="text" class="cart-page__discount-input field__input" placeholder="Discount code" id="CartPage-Discount" autocomplete="off">
                <button type="button" class="cart-page__discount-apply button button--secondary" onclick="
                  var code = document.getElementById('CartPage-Discount').value;
                  if(!code) return;
                  var btn = this;
                  btn.disabled = true;
                  btn.textContent = '...';
                  fetch('/discount/' + encodeURIComponent(code))
                    .then(function() { return fetch('/cart.js'); })
                    .then(function(r) { return r.json(); })
                    .then(function(cart) {
                      btn.disabled = false;
                      btn.textContent = 'Apply';
                      if(cart.total_discount > 0 || cart.cart_level_discount_applications.length > 0) {
                        var wrap = btn.closest('.cart-page__discount');
                        wrap.innerHTML = '<div class=\'cart-page__discount-success\'><svg width=\'14\' height=\'14\' viewBox=\'0 0 24 24\' fill=\'none\' stroke=\'#2e7d32\' stroke-width=\'2\' aria-hidden=\'true\'><polyline points=\'20 6 9 17 4 12\'/></svg> Code <strong>' + code + '</strong> applied!</div>';
                        location.reload();
                      } else {
                        var input = document.getElementById('CartPage-Discount');
                        input.style.borderColor = '#c62828';
                        var existing = btn.parentNode.parentNode.querySelector('.cart-page__discount-error');
                        if(!existing) {
                          var err = document.createElement('p');
                          err.className = 'cart-page__discount-error';
                          err.textContent = 'Invalid or expired code';
                          btn.parentNode.after(err);
                        }
                      }
                    })
                    .catch(function() { btn.disabled = false; btn.textContent = 'Apply'; });
                ">Apply</button>
              </div>
            </div>
          </div>
        {%- endif -%}

        {% for block in section.blocks %}
          {%- case block.type -%}
            {%- when '@app' -%}
              {% render block %}
            {%- when 'subtotal' -%}
              <div class="js-contents" {{ block.shopify_attributes }}>
                <div>
                  {%- if cart.cart_level_discount_applications.size > 0 -%}
                    <ul class="discounts list-unstyled" role="list" aria-label="{{ 'customer.order.discount' | t }}">
                      {%- for discount in cart.cart_level_discount_applications -%}
                        <li class="discounts__discount discounts__discount--position">
                          {%- render 'icon-discount' -%}
                          {{ discount.title }}
                          (-{{ discount.total_allocated_amount | money }})
                        </li>
                      {%- endfor -%}
                    </ul>
                  {%- endif -%}
                </div>

                {%- comment -%} Savings summary — matches cart drawer {%- endcomment -%}
                {%- assign total_savings = 0 -%}
                {%- for item in cart.items -%}
                  {%- if item.original_line_price > item.final_line_price -%}
                    {%- assign item_savings = item.original_line_price | minus: item.final_line_price -%}
                    {%- assign total_savings = total_savings | plus: item_savings -%}
                  {%- endif -%}
                {%- endfor -%}
                {%- if total_savings > 0 -%}
                  <div class="cart-savings">
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>
                    {%- assign savings_amount = total_savings | money -%}
                    {{ 'sections.cart.savings_html' | t: amount: savings_amount }}
                  </div>
                {%- endif -%}

                <div class="cart-page__shipping-line">
                  <span>{{ 'sections.cart.shipping_label' | t }}</span>
                  <span class="cart-page__shipping-free">{{ 'sections.cart.shipping_free' | t }}</span>
                </div>
                <div class="cart-page__country-checker">
                  {% render 'shipping-country-checker-trigger', context: 'cart' %}
                </div>
                <div class="totals">
                  <h2 class="totals__total">{{ 'sections.cart.estimated_total' | t }}</h2>
                  <p class="totals__total-value">{{ cart.total_price | money_with_currency }}</p>
                </div>

                <div class="cart-page__checkout-note caption-large">
                  <span>
                    {%- if cart.taxes_included -%}
                      Taxes included.
                    {%- else -%}
                      Taxes calculated at checkout.
                    {%- endif -%}
                  </span>
                  {%- if shop.shipping_policy.body != blank -%}
                    <details class="cart-page__policy-details">
                      <summary>Shipping details</summary>
                      <div class="rte">
                        {{ shop.shipping_policy.body }}
                      </div>
                    </details>
                  {%- endif -%}
                </div>
              </div>
            {%- else -%}
              {%- comment -%} Delivery timing remains hidden until address-specific checkout rates are confirmed. {%- endcomment -%}
              <div class="cart-page__delivery-estimate" hidden>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="1" y="3" width="15" height="13"/><polygon points="16 8 20 8 23 11 23 16 16 16 16 8"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
                {{ 'sections.cart.order_today_delivery' | t }} <strong><span class="js-delivery-date"></span></strong>
              </div>

              {%- comment -%} Storewide aggregate rating removed pending owner-provided proof. {%- endcomment -%}

              <div class="cart__ctas" {{ block.shopify_attributes }}>
                <button
                  type="submit"
                  id="checkout"
                  class="cart__checkout-button button"
                  name="checkout"
                  {% if cart == empty %}
                    disabled
                  {% endif %}
                  form="cart"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="margin-right:6px" aria-hidden="true"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
                  {{ 'sections.cart.checkout' | t }}
                </button>
              </div>

              {%- if additional_checkout_buttons -%}
                <div class="cart__dynamic-checkout-buttons additional-checkout-buttons">
                  {{ content_for_additional_checkout_buttons }}
                </div>
              {%- endif -%}

              <!-- Trust badges for cart page (matches cart drawer) -->
              <div class="cart-page__trust-badges">
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
                  <span>{{ 'sections.cart.trust.secure_checkout' | t }}</span>
                </div>
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
                  <span>{{ 'sections.cart.trust.ssl_encrypted' | t }}</span>
                </div>
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                  <span>{{ 'sections.cart.trust.free_shipping' | t }}</span>
                </div>
                <div class="trust-badge">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"/></svg>
                  <span>{{ 'sections.cart.trust.returns' | t }}</span>
                </div>
              </div>

              <!-- Accepted payment methods (matches cart drawer) -->
              <div class="cart-page__payment-icons">
                <span class="payment-icons__label">{{ 'sections.cart.we_accept' | t }}</span>
                <div class="payment-icons__list">
                  {%- for type in shop.enabled_payment_types -%}
                    {{ type | payment_type_svg_tag: class: 'payment-icon' }}
                  {%- endfor -%}
                </div>
              </div>

              {%- comment -%} Complete the Look — moved below all checkout elements {%- endcomment -%}
              {%- if cart != empty -%}
                <div class="cart-page__cross-sell">
                  <h2 class="cart-page__cross-sell-heading">{{ 'sections.cart.complete_the_look' | t }}</h2>
                  <div class="cart-page__cross-sell-grid">
                    {%- assign first_item = cart.items | first -%}
                    {%- assign cross_sell_count = 0 -%}
                    {%- for collection in first_item.product.collections -%}
                      {%- if cross_sell_count >= 4 -%}{%- break -%}{%- endif -%}
                      {%- for product in collection.products limit: 8 -%}
                        {%- if cross_sell_count >= 4 -%}{%- break -%}{%- endif -%}
                        {%- assign in_cart = false -%}
                        {%- for item in cart.items -%}
                          {%- if item.product.id == product.id -%}
                            {%- assign in_cart = true -%}
                            {%- break -%}
                          {%- endif -%}
                        {%- endfor -%}
                        {%- unless in_cart -%}
                          <div class="cart-page__cross-sell-item">
                            <a href="{{ product.url }}" class="cart-page__cross-sell-img-link">
                              {%- if product.featured_image -%}
                                <div class="cart-page__cross-sell-img-wrap">
                                  <img
                                    src="{{ product.featured_image | image_url: width: 400 }}"
                                    alt="{{ product.featured_image.alt | escape }}"
                                    width="150"
                                    height="{{ 150 | divided_by: product.featured_image.aspect_ratio | ceil }}"
                                    loading="lazy"
                                    class="cart-page__cross-sell-img"
                                  >
                                </div>
                              {%- endif -%}
                            </a>
                            <div class="cart-page__cross-sell-info">
                              <a href="{{ product.url }}" class="cart-page__cross-sell-name">{{ product.title | escape | split: ' | ' | first }}</a>
                              <span class="cart-page__cross-sell-price">{{ product.price | money }}</span>
                            </div>
                          </div>
                          {%- assign cross_sell_count = cross_sell_count | plus: 1 -%}
                        {%- endunless -%}
                      {%- endfor -%}
                    {%- endfor -%}
                  </div>
                </div>
              {%- endif -%}

          {%- endcase -%}
        {% endfor %}

        <div id="cart-errors"></div>
      </div>
    </div>
  </div>
</div>

{% schema %}
{
  "name": "t:sections.main-cart-footer.name",
  "class": "cart__footer-wrapper",
  "settings": [
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "label": "t:sections.all.colors.label",
      "default": "scheme-1"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_top",
      "default": 40
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 100,
      "step": 4,
      "unit": "px",
      "label": "t:sections.all.padding.padding_bottom",
      "default": 40
    }
  ],
  "blocks": [
    {
      "type": "subtotal",
      "name": "t:sections.main-cart-footer.blocks.subtotal.name",
      "limit": 1
    },
    {
      "type": "buttons",
      "name": "t:sections.main-cart-footer.blocks.buttons.name",
      "limit": 1
    },
    {
      "type": "@app"
    }
  ]
}
{% endschema %}

{%- comment -%}
  PDP buy-column canonical block order (CRO Phase 2/3 reference):

    1.  Title
    2.  Price (+ sale anchor)
    3.  Variant picker (with numbered step headings on multi-option SKUs:
        "1. Who is this for? / 2. Choose piece / 3. Choose size")
    4.  Size guide trigger (lives inside the Purchase Confidence panel)
    5.  Buy buttons — primary CTA
        - On matching-set products: matching-set CTA reads as primary
          and the single-piece ATC is demoted to outline-style
          (via :has() in component-product-desktop-ux.css)
    6.  Compressed trust row + three promise rows + collapsed details
        (snippets/pdp-purchase-confidence.liquid)
    7.  Photos / details / care / full size chart (existing accordions)
    8.  Similar styles / recommendations
    9.  Reviews (kept low; above-fold review count suppressed via
        snippets/pdp-review-social-proof.liquid)

  Theme-editor block order can be tweaked per-product, but please keep
  the above as the canonical sequence — each step exists for a CRO
  reason documented in the corresponding snippet header.
{%- endcomment -%}
<section
  id="MainProduct-{{ section.id }}"
  class="section-{{ section.id }}-padding gradient color-{{ section.settings.color_scheme }}"
  data-section="{{ section.id }}"
>
  {%- liquid
    assign product_collection_handles = product.collections | map: 'handle' | join: '|'
    assign product_subcategory = product.metafields.custom.subcategory | default: blank
    assign product_subcategory_handle = product_subcategory | handleize
    assign product_title_downcase = product.title | downcase
    assign product_tags_downcase = product.tags | join: '|' | downcase
    assign mobile_gallery_ratio = product.featured_media.preview_image.aspect_ratio | default: product.featured_media.aspect_ratio | default: 1.0
    for product_media in product.media
      assign product_media_ratio = product_media.preview_image.aspect_ratio | default: product_media.aspect_ratio | default: blank
      if product_media_ratio != blank and product_media_ratio < mobile_gallery_ratio
        assign mobile_gallery_ratio = product_media_ratio
      endif
    endfor
    assign has_family_sets_context = false
    if product_collection_handles contains 'family-sets' or product_subcategory_handle == 'family-sets'
      assign has_family_sets_context = true
    endif
    assign has_matching_set_context = has_family_sets_context
    if product_collection_handles contains 'mommy-and-me' or product_collection_handles contains 'daddy-and-me' or product_collection_handles contains 'family-matching' or product_collection_handles contains 'matching-family' or product_collection_handles contains 'couples' or product_title_downcase contains 'mommy and me' or product_title_downcase contains 'daddy and me' or product_title_downcase contains 'family matching' or product_title_downcase contains 'matching set' or product_tags_downcase contains 'mommy-and-me' or product_tags_downcase contains 'daddy-and-me' or product_tags_downcase contains 'family-matching' or product_tags_downcase contains 'matching-family'
      assign has_matching_set_context = true
    endif
  -%}

  <div class="page-width page-width--product-breadcrumbs">
    {% render 'breadcrumbs' %}
  </div>

  {{ 'section-main-product.css' | asset_url | stylesheet_tag }}
  {{ 'component-accordion.css' | asset_url | stylesheet_tag }}
  {{ 'component-price.css' | asset_url | stylesheet_tag }}
  {{ 'component-card.css' | asset_url | stylesheet_tag }}
  {{ 'component-slider.css' | asset_url | stylesheet_tag }}
  {{ 'component-rating.css' | asset_url | stylesheet_tag }}
  {{ 'component-deferred-media.css' | asset_url | stylesheet_tag }}
  {{ 'component-product-desktop-ux-ruler-sync.css' | asset_url | stylesheet_tag }}
  {{ 'component-product-description.css' | asset_url | stylesheet_tag }}
  {% unless product.has_only_default_variant %}
    {{ 'component-product-variant-picker.css' | asset_url | stylesheet_tag }}
    {{ 'component-swatch-input.css' | asset_url | stylesheet_tag }}
    {{ 'component-swatch.css' | asset_url | stylesheet_tag }}
  {% endunless %}
  {%- if product.quantity_price_breaks_configured? -%}
    {{ 'component-volume-pricing.css' | asset_url | stylesheet_tag }}
  {%- endif -%}

  {%- style -%}
    .section-{{ section.id }}-padding {
      padding-top: {{ section.settings.padding_top | times: 0.75 | round: 0 }}px;
      padding-bottom: {{ section.settings.padding_bottom | times: 0.75 | round: 0 }}px;
    }

    @media screen and (min-width: 750px) {
      .section-{{ section.id }}-padding {
        padding-top: {{ section.settings.padding_top }}px;
        padding-bottom: {{ section.settings.padding_bottom }}px;
      }
    }

    /* Reserve PDP gallery height before deferred product CSS finishes loading. */
    #MainProduct-{{ section.id }} {
      --dlm-mobile-gallery-ratio: {{ mobile_gallery_ratio }};
    }

    #MainProduct-{{ section.id }} .product-media-container {
      aspect-ratio: var(--preview-ratio, 1);
    }

    #MainProduct-{{ section.id }} .product-media-container .media {
      display: block;
      position: relative;
      overflow: hidden;
      aspect-ratio: var(--preview-ratio, 1);
      padding-top: 0 !important;
    }

    #MainProduct-{{ section.id }} .product-media-container .media > img {
      display: block;
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      max-width: 100%;
      object-fit: contain;
      object-position: center top;
    }

    #MainProduct-{{ section.id }} .scroll-trigger.animate--slide-in,
    #MainProduct-{{ section.id }} .scroll-trigger.animate--fade-in {
      animation: none !important;
      opacity: 1 !important;
      transform: none !important;
    }

    #MainProduct-{{ section.id }} .dlm-reference-ui .share-button {
      display: none !important;
      margin: 0 !important;
    }

    #MainProduct-{{ section.id }} .matching-size-guide__snapshot--reserved:empty {
      display: block !important;
      min-height: 24.3rem;
      visibility: hidden;
    }

    @media screen and (max-width: 749px) {
      #MainProduct-{{ section.id }} .product__media-list .product__media-item,
      #MainProduct-{{ section.id }} .product-media-container,
      #MainProduct-{{ section.id }} .product-media-container .product__modal-opener,
      #MainProduct-{{ section.id }} .product-media-container .media {
        aspect-ratio: var(--dlm-mobile-gallery-ratio, var(--preview-ratio, 1));
      }

      #MainProduct-{{ section.id }} .product__media-list .product__media-item,
      #MainProduct-{{ section.id }} .product-media-container,
      #MainProduct-{{ section.id }} .product-media-container .product__modal-opener {
        height: auto;
      }

      #MainProduct-{{ section.id }} .product-media-container .media {
        height: 100%;
      }
    }

    /* PDP screenshot-style hard override scoped to this product section */
    #MainProduct-{{ section.id }},
    #MainProduct-{{ section.id }}.gradient,
    #MainProduct-{{ section.id }} .product__info-wrapper,
    #MainProduct-{{ section.id }} .dlm-reference-ui,
    #MainProduct-{{ section.id }} .dlm-reference-ui .product__title,
    #MainProduct-{{ section.id }} .dlm-reference-ui [id^='price-'],
    #MainProduct-{{ section.id }} .dlm-reference-ui .installment,
    #MainProduct-{{ section.id }} .dlm-reference-ui .shopify-installments,
    #MainProduct-{{ section.id }} .dlm-reference-ui shopify-payment-terms {
      background: #ffffff !important;
    }

    #MainProduct-{{ section.id }} .dlm-reference-ui {
      --dlm-surface-radius: 2.2rem;
      --dlm-control-surface-padding: 0.75rem;
      --dlm-card-bg: #ffffff;
      --dlm-control-surface-bg: #ffffff;
      --dlm-control-pill-bg: #ffffff;
      --dlm-control-pill-border: #dfe8f5;
      width: 100%;
      max-width: 100% !important;
      padding: 2.2rem 1.8rem 2.6rem !important;
      border: 0 !important;
      border-radius: var(--dlm-surface-radius) !important;
      background: var(--dlm-card-bg) !important;
      box-shadow: none !important;
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif !important;
