    <div class="product product--{{ section.settings.media_size }} product--{{ section.settings.media_position }} product--{{ section.settings.gallery_layout }} product--mobile-{{ section.settings.mobile_thumbnails }} grid grid--1-col {% if product.media.size > 0 %}grid--2-col-tablet{% else %}product--no-media{% endif %}">
      <div class="grid__item product__media-wrapper">
        {% render 'product-media-gallery', variant_images: variant_images %}
      </div>
      <div class="product__info-wrapper grid__item{% if settings.page_width > 1400 and section.settings.media_size == "small" %} product__info-wrapper--extra-padding{% endif %}{% if settings.animations_reveal_on_scroll %} scroll-trigger animate--slide-in{% endif %}">
        <product-info
          id="ProductInfo-{{ section.id }}"
          data-section="{{ section.id }}"
          data-url="{{ product.url }}"
          {%- comment -%}
            CRO redesign (May 2026): expose has_matching_set_context to
            CSS/JS so the redesigned bundle UI (single CTA, family-member
            cards, compressed spacing, collapsed Purchase Confidence) can
            be scoped cleanly with [data-has-matching-set="true"] and
            non-bundle products keep their Dawn-default behavior.
          {%- endcomment -%}
          data-has-matching-set="{% if has_matching_set_context %}true{% else %}false{% endif %}"
          class="product__info-container dlm-reference-ui{% if section.settings.enable_sticky_info %} product__column-sticky{% endif %}{% if has_matching_set_context %} product__info-container--matching-set{% endif %}"
        >


 {%- assign product_form_id = 'product-form-' | append: section.id -%}
 {%- assign taxonomy_category1 = product.metafields.custom.category1 | default: '' | strip -%}
 {%- assign taxonomy_subcategory = product.metafields.custom.subcategory | default: '' | strip -%}
 {%- assign taxonomy_subcategory2 = product.metafields.custom.subcategory2 | default: '' | strip -%}
 {%- assign taxonomy_type = product.metafields.custom.type | default: product.type | default: '' | strip -%}
 {%- assign taxonomy_style = product.metafields.custom.style | default: '' | strip -%}
 {%- assign taxonomy_pattern = product.metafields.custom.pattern | default: '' | strip -%}
 {%- for tag in product.tags -%}
   {%- assign normalized_tag = tag | strip -%}
   {%- assign normalized_tag_downcase = normalized_tag | downcase -%}
   {%- if taxonomy_category1 == blank and normalized_tag_downcase contains 'category1:' -%}
     {%- assign taxonomy_category1 = normalized_tag | split: ':' | last | strip -%}
   {%- elsif taxonomy_category1 == blank and normalized_tag_downcase contains 'category:' -%}
     {%- assign taxonomy_category1 = normalized_tag | split: ':' | last | strip -%}
   {%- endif -%}
   {%- if taxonomy_subcategory == blank and normalized_tag_downcase contains 'subcategory:' -%}
     {%- assign taxonomy_subcategory = normalized_tag | split: ':' | last | strip -%}
   {%- endif -%}
   {%- if taxonomy_subcategory2 == blank and normalized_tag_downcase contains 'subcategory2:' -%}
     {%- assign taxonomy_subcategory2 = normalized_tag | split: ':' | last | strip -%}
   {%- endif -%}
   {%- if taxonomy_type == blank and normalized_tag_downcase contains 'type:' -%}
     {%- assign taxonomy_type = normalized_tag | split: ':' | last | strip -%}
   {%- endif -%}
   {%- if taxonomy_style == blank and normalized_tag_downcase contains 'style:' -%}
     {%- assign taxonomy_style = normalized_tag | split: ':' | last | strip -%}
   {%- endif -%}
   {%- if taxonomy_pattern == blank and normalized_tag_downcase contains 'pattern:' -%}
     {%- assign taxonomy_pattern = normalized_tag | split: ':' | last | strip -%}
   {%- endif -%}
 {%- endfor -%}

          {%- for block in section.blocks -%}
            {%- case block.type -%}
              {%- when '@app' -%}
                {% render block %}
              {%- when 'text' -%}
                <p
                  class="product__text inline-richtext{% if block.settings.text_style == 'uppercase' %} caption-with-letter-spacing{% elsif block.settings.text_style == 'subtitle' %} subtitle{% endif %}"
                  {{ block.shopify_attributes }}
                >
                  {{- block.settings.text -}}
                </p>
              {%- when 'title' -%}
                <div class="product__title" {{ block.shopify_attributes }}>
                  {%- liquid
                    assign clean_title = product.title | split: ' | ' | first
                    assign title_locale_root = request.locale.iso_code | default: localization.language.iso_code | default: '' | split: '-' | first | downcase
                    if product.handle == 'golden-daisy-mommy-and-me-set' and title_locale_root == 'en'
                      assign clean_title = 'Golden Daisy Mommy & Me Matching Separates'
                    endif
                  -%}
                  <h1 class="product__title-text">{{ clean_title | escape }}</h1>
                </div>
              {%- when 'price' -%}
                {%- comment -%}
                  CRO redesign (May 2026): expose computed savings % on the
                  price container so CSS can render a 'Save Z%' badge in
                  the matching-set scope without forking snippets/price.liquid.
                {%- endcomment -%}
                {%- liquid
                  assign pdp_variant = product.selected_or_first_available_variant
                  assign pdp_sale_pct = 0
                  assign pdp_show_price_badges = true
                  assign pdp_use_variant_price = true
                  assign pdp_show_price_range = false
                  assign pdp_show_compare_at_price = true
                  if has_matching_set_context
                    assign pdp_show_price_badges = false
                    assign pdp_show_compare_at_price = false
                    if product.selected_variant == nil
                      assign pdp_use_variant_price = false
                      assign pdp_show_price_range = true
                    endif
                  elsif pdp_variant.compare_at_price and pdp_variant.compare_at_price > pdp_variant.price
                    assign pdp_diff = pdp_variant.compare_at_price | minus: pdp_variant.price
                    assign pdp_diff_x100 = pdp_diff | times: 100
                    assign pdp_sale_pct = pdp_diff_x100 | divided_by: pdp_variant.compare_at_price
                  endif
                -%}
                <div
                  id="price-{{ section.id }}"
                  role="status"
                  data-pdp-sale-percent="{{ pdp_sale_pct }}"
                  {{ block.shopify_attributes }}
                >
                  {%- render 'price',
                    product: product,
                    use_variant: pdp_use_variant_price,
                    show_price_range: pdp_show_price_range,
                    show_compare_at_price: pdp_show_compare_at_price,
                    show_badges: pdp_show_price_badges,
                    show_sold_out_badge: false,
                    price_class: 'price--large'
                  -%}
                  {%- if pdp_sale_pct > 0 -%}
                    <span class="pdp-save-pill" aria-hidden="true">Save {{ pdp_sale_pct }}%</span>
                  {%- endif -%}
                </div>
                {%- if product.quantity_price_breaks_configured? -%}
                  <div class="volume-pricing-note" id="Volume-Note-{{ section.id }}">
                    <span>{{ 'products.product.volume_pricing.note' | t }}</span>
                  </div>
                {%- endif -%}
                <div class="product__tax caption rte" style="display:none;">
                  {%- if cart.taxes_included -%}
                    {{ 'products.product.include_taxes' | t }}
                  {%- endif -%}
                  {%- if shop.shipping_policy.body != blank -%}
                    {{ 'products.product.shipping_policy_html' | t: link: shop.shipping_policy.url }}
                  {%- endif -%}
                </div>
                {%- if product.selling_plan_groups.size > 0 -%}
                  <div {{ block.shopify_attributes }}>
                    {%- assign product_form_installment_id = 'product-form-installment-' | append: section.id -%}
                    {%- form 'product', product, id: product_form_installment_id, class: 'installment caption-large' -%}
                      <input type="hidden" name="id" value="{{ product.selected_or_first_available_variant.id }}">
                      {{ form | payment_terms }}
                    {%- endform -%}
                  </div>
                {%- endif -%}
              {%- when 'inventory' -%}
                <p
                  class="product__inventory{% if block.settings.text_style == 'uppercase' %} caption-with-letter-spacing{% elsif block.settings.text_style == 'subtitle' %} subtitle{% endif %}{% if product.selected_or_first_available_variant.inventory_management != 'shopify' %} visibility-hidden{% endif %}"
                  {{ block.shopify_attributes }}
                  id="Inventory-{{ section.id }}"
                  role="status"
                >
                  {%- if product.selected_or_first_available_variant.inventory_management == 'shopify' -%}
                    {%- if product.selected_or_first_available_variant.inventory_quantity > 0 -%}
                      {%- if product.selected_or_first_available_variant.inventory_quantity
                          <= block.settings.inventory_threshold
                      -%}
                        <svg width="15" height="15" aria-hidden="true">
                          <circle cx="7.5" cy="7.5" r="7.5" fill="rgb(238,148,65, 0.3)"/>
                          <circle cx="7.5" cy="7.5" r="5" stroke="rgb(255, 255, 255)" stroke-width="1" fill="rgb(238,148,65)"/>
                        </svg>
                        {%- if block.settings.show_inventory_quantity -%}
                          {{-
                            'products.product.inventory_low_stock_show_count'
                            | t: quantity: product.selected_or_first_available_variant.inventory_quantity
                          -}}
                        {%- else -%}
                          {{- 'products.product.inventory_low_stock' | t -}}
                        {%- endif -%}
                      {%- else -%}
                        <svg width="15" height="15" aria-hidden="true">
                          <circle cx="7.5" cy="7.5" r="7.5" fill="rgb(62,214,96, 0.3)"/>
                          <circle cx="7.5" cy="7.5" r="5" stroke="rgb(255, 255, 255)" stroke-width="1" fill="rgb(62,214,96)"/>
                        </svg>
                        {%- if block.settings.show_inventory_quantity -%}
                          {{-
                            'products.product.inventory_in_stock_show_count'
                            | t: quantity: product.selected_or_first_available_variant.inventory_quantity
                          -}}
                        {%- else -%}
                          {{- 'products.product.inventory_in_stock' | t -}}
                        {%- endif -%}
                      {%- endif -%}
                    {%- else -%}
                      {%- if product.selected_or_first_available_variant.inventory_policy == 'continue' -%}
                        <svg width="15" height="15" aria-hidden="true">
                          <circle cx="7.5" cy="7.5" r="7.5" fill="rgb(62,214,96, 0.3)"/>
                          <circle cx="7.5" cy="7.5" r="5" stroke="rgb(255, 255, 255)" stroke-width="1" fill="rgb(62,214,96)"/>
                        </svg>
                        {{- 'products.product.inventory_out_of_stock_continue_selling' | t -}}
                      {%- else -%}
                        <svg width="15" height="15" aria-hidden="true">
                          <circle cx="7.5" cy="7.5" r="7.5" fill="rgb(200,200,200, 0.3)"/>
                          <circle cx="7.5" cy="7.5" r="5" stroke="rgb(255, 255, 255)" stroke-width="1" fill="rgb(200,200,200)"/>
                        </svg>
                        {{- 'products.product.inventory_out_of_stock' | t -}}
                      {%- endif -%}
                    {%- endif -%}
                  {%- endif -%}
                </p>
              {%- when 'description' -%}
                {%- if product.description != blank -%}
